/**
 * Reference-surface types for the v2 catalog.
 *
 * A *catalog fragment* describes one entity's **reference surface** — exactly
 * what a referencing entity file needs to name it safely, and nothing more.
 * For a behavioral entity (automation / agent / skill) that is just its
 * **handle** (the join key, resolved to an id at deploy time) plus its display
 * name for readability. **No id appears in the catalog** — identity lives in
 * state (`src/deploy/state`).
 *
 * The `__kind` discriminant lets a builder's reference parameter accept exactly
 * the right kind of handle (`runAutomation(ref: AutomationRef)`) and makes the
 * fragment self-describing. These are the shapes the fragment renderer emits
 * and the (forthcoming) builders consume — the single shared contract.
 *
 * Two groups of kinds share this shape. **Behavioral entities**
 * (automation/agent/skill) are author-managed: imported reference-only, then
 * deployed. **Reference-surface entities** — an app's *fields* and *search
 * tables*, and org-owned *cloud links* / AI provider *connectors* — are never
 * deployed through v2; they're imported so a builder can point at them by typed
 * handle (`app.fields.severity`, `connectors.bedrockSonnet`). Field refs carry
 * a little extra schema (`fieldType`) for authoring-time type safety; that
 * schema is authoring-only — at the wire boundary `resolvePayload` replaces the
 * whole token with the resolved id, discarding it.
 */
import type { AiProviderLlmModel, AiProviderType } from "./ai-provider-models.js";
/**
 * Kinds a catalog fragment can describe:
 *   - behavioral, app-owned, deployable — `automation` / `agent` / `skill`;
 *   - reference-only, app- or element-owned — `field`;
 *   - reference-only, element- or table-owned — `searchTable`;
 *   - reference-only, org-owned         — `cloudLink` / `connector`;
 *   - the app or element itself, resolved by
 *     handle against the app registry rather than a state scope;
 *   - nested under an automation         — `triggerParameter` / `outputProperty`,
 *     resolved to the current-version param/output id via the parent
 *     automation's state binding.
 */
export type CatalogRefKind = "automation" | "agent" | "agent-evaluation" | "chart" | "dashboard" | "widget" | "skill" | "visual-flow" | "approvalChain" | "table" | "tableColumn" | "cloudLink" | "storedFunction" | "procedure" | "field" | "searchTable" | "documentModel" | "documentModelField" | "connector" | "aiProvider" | "category" | "group" | "phoneProvider" | "phone-service" | "datamine" | "app" | "element" | "task" | "triggerParameter" | "outputProperty";
/**
 * The reference surface for a catalog entity. `handle` is the stable join key
 * (no id); `name` is for readability/diagnostics, never a match key.
 */
export interface CatalogRef<K extends CatalogRefKind = CatalogRefKind, RefName extends string = string, Parent extends string | undefined = string | undefined> {
    readonly __kind: K;
    readonly refName: RefName;
    readonly name: string;
    /**
     * The owning **parent**'s handle — the app, element, or table that
     * owns this entity — so a reference is self-describing ("app X's automation
     * foo") and an entity can derive its parent from its own ref. Absent for
     * org-owned kinds (cloud links, connectors), which resolve against the single
     * org scope by kind.
     */
    readonly parent?: Parent;
}
export interface AutomationRef<TTrigger = unknown, TOutput = unknown> extends CatalogRef<"automation"> {
    /**
     * Always `undefined` at runtime — a typed phantom that lets other entities inspect the trigger
     * output shape at compile time (e.g. `typeof app.automations.sendSurvey.trigger`).
     */
    readonly trigger?: TTrigger;
    /**
     * Always `undefined` at runtime — a typed phantom for the accumulated task output shape
     * (e.g. `typeof app.automations.sendSurvey.output`).
     */
    readonly output?: TOutput;
}
export type AgentRef<Parent extends string = string, RefName extends string = string> = CatalogRef<"agent", RefName, Parent>;
export type AgentEvaluationRef<Parent extends string = string, RefName extends string = string> = CatalogRef<"agent-evaluation", RefName, Parent>;
export type ChartRef<Parent extends string = string, RefName extends string = string> = CatalogRef<"chart", RefName, Parent>;
export type DashboardRef<Parent extends string = string, RefName extends string = string> = CatalogRef<"dashboard", RefName, Parent>;
export type WidgetRef<Parent extends string = string, RefName extends string = string> = CatalogRef<"widget", RefName, Parent>;
