/** Public reference to an AI service/model selected for runtime use. */
export type AiServiceRef = CatalogRef<"connector">;
/** @internal Backend compatibility name. Prefer {@link AiServiceRef} on authoring surfaces. */
export type ConnectorRef = AiServiceRef;
/**
 * An AI provider reference that also exposes its enabled connectors as a
 * nested ref bag — models are referenceable *on* the provider
 * (`catalog.aiProviders.<provider>.models.<model>`), the same nested-ref-bag
 * shape `AutomationCatalogRef`/`FileReaderCatalogRef` already use. Reference
 * only — the provider must already exist on the platform; there is no
 * create/deploy path (src/CLAUDE.md). Generic over `T` so `type: "anthropic"`
 * narrows which models are valid in `models` (see `AiProviderLlmModel`).
 */
export interface AiProviderRef<T extends AiProviderType = AiProviderType> extends CatalogRef<"aiProvider"> {
    /** Which AI provider family this is (e.g. "anthropic", "bedrock") — build maps it to the matching `elementum_<type>_ai_provider` terraform data source; authored source never names the resource type directly. */
    readonly type: T;
    /**
     * Each entry is either a reference to an already-pulled connector
     * (`connectorRef({ name })`, what `pull org` always emits) or a bare model
     * literal naming a connector to create for that model — type-checked
     * against `T`'s valid models. The create path has no build/authoring-
     * location wiring yet; this is the type surface only.
     */
    readonly models?: Readonly<Record<string, ConnectorRef | AiProviderLlmModel<T>>>;
}
