/** Org-owned reference identities from `elementum pull org --data-only` (pristine-refactor). */
export type CategoryRef = CatalogRef<"category">;
export type GroupRef = CatalogRef<"group">;
export type PhoneProviderRef = CatalogRef<"phoneProvider">;
export type PhoneServiceRef<Parent extends string = string, RefName extends string = string> = CatalogRef<"phone-service", RefName, Parent>;
